#!/usr/bin/env python3
"""Run SFS-1 hosted qualification; only new disposable regular images are written.

Initial baseline is a preserved snapshot, not regenerated by this runner. Logs from
failed development attempts remain separate. --integrity-only rechecks final bytes.
No QEMU, native mount, device formatting, commit or network access.
"""
import argparse, collections, gzip, hashlib, json, os, platform, re, subprocess, tempfile, time, tomllib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/audit/sunfs/sfs-1'
RAW=OUT/'raw'
CRATES=['sunlight-sunfs','sunlight-sunfs-lab','sunlight-sunfs-check']

def digest(path):
    h=hashlib.sha256()
    with path.open('rb') as stream:
        for b in iter(lambda:stream.read(1048576),b''):h.update(b)
    return h.hexdigest()
def save(name,value):
    (OUT/name).write_text(json.dumps(value,indent=2)+'\n')
def source_hashes():
    paths=[ROOT/'Cargo.toml',ROOT/'Cargo.lock']
    for crate in CRATES:paths.extend(p for p in (ROOT/crate).rglob('*') if p.is_file())
    paths.extend([Path(__file__),ROOT/'tools/sunfs_golden.py',ROOT/'tools/sunfs_reproduce.py'])
    return {str(p.relative_to(ROOT)):digest(p) for p in sorted(paths) if p.exists()}
commands=[]
def run(args,name,expected=0,env=None):
    start=time.time_ns()
    with (RAW/name).open('w') as log:
        p=subprocess.run(args,cwd=ROOT,stdout=log,stderr=subprocess.STDOUT,env=env)
    commands.append({'argv':list(map(str,args)),'log':'raw/'+name,'returncode':p.returncode,'expected':expected,'elapsed_ns':time.time_ns()-start,'status':'PASS' if p.returncode==expected else 'FAIL'})
    print(f'{name}: exit {p.returncode}',flush=True)
    if p.returncode!=expected:raise RuntimeError(f'failed {name}; preserve the log')
    return (RAW/name).read_text()
def cargo(action,packages,extra=()):
    return ['cargo',action,*sum((['-p',p] for p in packages),[]),'--offline','--locked',*extra]
def integration():
    binary=ROOT/'target/x86_64-unknown-linux-gnu/release'
    fmt=str(binary/'sunfs-format');chk=str(binary/'sunfs-check')
    records=[]
    def invoke(args,code,log):
        text=run(args,log,code);records.append({'argv':list(map(str,args)),'exit':code,'log':'raw/'+log});return text
    with tempfile.TemporaryDirectory(prefix='sunfs-sfs1-') as directory:
        path=Path(directory)/'disposable.img'
        start=time.perf_counter_ns();invoke([fmt,'--image',str(path),'--size','16MiB','--confirm-disposable'],0,'cli-format.log');format_ns=time.perf_counter_ns()-start
        original=digest(path)
        start=time.perf_counter_ns();invoke([chk,'--image',str(path)],0,'cli-check-clean.log');check_ns=time.perf_counter_ns()-start
        assert digest(path)==original
        invoke([fmt,'--image',str(path),'--size','16MiB','--confirm-disposable'],2,'cli-existing-refused.log');assert digest(path)==original
        alias=Path(directory)/'alias.img';alias.symlink_to(path)
        invoke([fmt,'--image',str(alias),'--size','16MiB','--confirm-disposable'],2,'cli-symlink-refused.log');assert digest(path)==original
        invoke([fmt,'--image',str(Path(directory)/'unconfirmed.img'),'--size','16MiB'],2,'cli-confirmation-refused.log');assert not (Path(directory)/'unconfirmed.img').exists()
        data=bytearray(path.read_bytes());data[3*4096+64]^=1
        broken=Path(directory)/'degraded.img';broken.write_bytes(data);before=digest(broken)
        invoke([chk,'--image',str(broken)],1,'cli-check-degraded.log');assert before==digest(broken)
        data[2*4096+64]^=1;broken.write_bytes(data);before=digest(broken)
        invoke([chk,'--image',str(broken)],2,'cli-check-corrupt.log');assert before==digest(broken)
    return records,{'volume_mib':16,'format_process_ns':format_ns,'checker_process_ns':check_ns,'includes_process_start_and_host_sync':True}
def integrity():
    baseline=json.loads((OUT/'source-baseline.json').read_text())
    changed=[];missing=[]
    for name,expected in baseline['sha256'].items():
        p=ROOT/name
        if not p.is_file() or p.is_symlink():missing.append(name)
        elif digest(p)!=expected:changed.append(name)
    allowed={'Cargo.toml','Cargo.lock'}
    unexpected=[p for p in changed if p not in allowed]
    old=json.loads((ROOT/'docs/audit/sunfs/sfs-0/source-integrity-manifest.json').read_text())
    sfs0_errors=[name for name,value in old['outputs_sha256'].items() if digest(ROOT/name)!=value]
    outputs=[]
    for directory in [OUT,*(ROOT/c for c in CRATES)]:outputs.extend(p for p in directory.rglob('*') if p.is_file() and not p.is_symlink())
    outputs.extend(ROOT/'docs/filesystems/sunfs'/name for name in ['sfs-1-storage-laboratory.md','adr/0002-sfs1-experimental-codec.md'])
    outputs.extend(ROOT/'tools'/name for name in ['sunfs_golden.py','sunfs_validate.py','sunfs_reproduce.py'])
    outputs.extend([ROOT/'Cargo.toml',ROOT/'Cargo.lock'])
    excluded={OUT/'source-integrity.json'}
    hashes={str(p.relative_to(ROOT)):digest(p) for p in sorted(set(outputs)) if p.exists() and p not in excluded}
    paths=subprocess.check_output(['git','ls-files','-z','--cached','--others','--exclude-standard'],cwd=ROOT).decode().split('\0')
    allowed_new=('sunlight-sunfs/','sunlight-sunfs-lab/','sunlight-sunfs-check/','docs/audit/sunfs/sfs-1/')
    extra_allowed={'docs/filesystems/sunfs/adr/0002-sfs1-experimental-codec.md','docs/filesystems/sunfs/sfs-1-storage-laboratory.md','tools/sunfs_golden.py','tools/sunfs_validate.py','tools/sunfs_reproduce.py'}
    unexpected_new=[p for p in paths if p and p not in baseline['sha256'] and not p.startswith(allowed_new) and p not in extra_allowed and (ROOT/p).is_file() and not (ROOT/p).is_symlink()]
    result={'status':'PASS' if not (unexpected or missing or sfs0_errors or unexpected_new) else 'FAIL','incoming_regular_files':len(baseline['sha256']),'modified_incoming':changed,'unexpected_modified':unexpected,'missing':missing,'sfs0_output_errors':sfs0_errors,'unexpected_new':unexpected_new,'outputs_sha256':hashes,'self_hash_excluded':True,'ignored_artifacts_and_symlink_metadata_excluded':True,'git_diff_check':subprocess.run(['git','diff','--check'],cwd=ROOT,capture_output=True,text=True).returncode}
    save('source-integrity.json',result)
    assert result['status']=='PASS' and result['git_diff_check']==0,result
    # Verify every generated digest against current bytes after writing the manifest.
    assert all(digest(ROOT/name)==value for name,value in hashes.items())
    print(f'integrity: {len(baseline["sha256"])} incoming files; SFS-0 preserved; {len(hashes)} outputs verified',flush=True)
    return result

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--integrity-only',action='store_true');args=parser.parse_args()
    if args.integrity_only:integrity();return
    sources=source_hashes()
    save('architecture-implementation-map.json',{'status':'PASS','core':{'crate':'sunlight-sunfs','no_std':True,'uses_alloc':True,'normal_dependencies':[],'files':['codec.rs','geometry.rs','block.rs','bootstrap.rs']},'hosted':{'crate':'sunlight-sunfs-lab','normal_dependencies':['sunlight-sunfs'],'dev_dependencies':['sunlight-sunfs-check']},'checker':{'crate':'sunlight-sunfs-check','normal_dependencies':['sunlight-sunfs'],'semantic_owner':'src/lib.rs Walker and independent selection','forbidden_calls':['bootstrap','Geometry::calculate','publish'],'inspection':'checker source imports codec only; no engine recovery oracle'},'production_integration':False,'format_decision':'docs/filesystems/sunfs/adr/0002-sfs1-experimental-codec.md'})
    run(['python3','tools/sunfs_golden.py'],'golden-final.log')
    # Golden regeneration must be byte-identical to the checked fixtures.
    assert source_hashes()==sources,'golden fixtures changed unexpectedly'
    run(cargo('check',['sunlight-sunfs'],['--target','x86_64-unknown-none']),'core-no-std-final.log')
    env=dict(os.environ,SUNFS_EVIDENCE_DIR=str(RAW))
    test_logs={}
    for profile in ['dev','release']:
        extra=['--target','x86_64-unknown-linux-gnu']+(['--release'] if profile=='release' else [])
        # Distinct corpus/trace outputs per profile; preserve both campaigns.
        directory=RAW/profile;directory.mkdir(exist_ok=True)
        env['SUNFS_EVIDENCE_DIR']=str(directory)
        test_logs[profile]=run(cargo('test',CRATES,[*extra,'--','--nocapture']),f'tests-{profile}-final.log',env=env)
    regress=run(cargo('test',['sunlight-block','sunlight-fat','sunlight-fs'],['--lib','--target','x86_64-unknown-linux-gnu']),'storage-regressions-final.log')
    run(cargo('clippy',CRATES,['--all-targets','--target','x86_64-unknown-linux-gnu','--','-D','warnings']),'clippy-final.log')
    run(cargo('build',['sunlight-sunfs-lab','sunlight-sunfs-check'],['--bins','--release','--target','x86_64-unknown-linux-gnu']),'host-bins-final.log')
    performance=[]
    for profile in ['dev','release']:
        text=run(cargo('run',['sunlight-sunfs-lab'],['--example','baseline','--target','x86_64-unknown-linux-gnu',*(['--release'] if profile=='release' else [])]),f'performance-{profile}-final.log')
        performance.extend(dict(json.loads(line),profile=profile) for line in text.splitlines() if line.startswith('{'))
    cli,cli_timing=integration()
    # Compress only images created by tests. SFS-0 and user storage are never touched.
    for profile in ['dev','release']:
        for name in ['nonempty','bootstrap']:
            image=RAW/profile/(name+'.img')
            assert image.exists()
            with (image.with_suffix('.img.gz')).open('wb') as output:output.write(gzip.compress(image.read_bytes(),mtime=0))
            image.unlink()  # Generated test artifact only; retain compressed reproducer.
    counts={profile:sum(int(n) for n in re.findall(r'test result: ok\. (\d+) passed',text)) for profile,text in test_logs.items()}
    assert counts=={'dev':24,'release':24},counts
    regression_counts=list(map(int,re.findall(r'test result: ok\. (\d+) passed',regress)))
    assert regression_counts==[29,9,101],regression_counts
    old_lock=tomllib.loads(subprocess.check_output(['git','show','HEAD:Cargo.lock'],cwd=ROOT).decode())
    new_lock=tomllib.loads((ROOT/'Cargo.lock').read_text())
    new_lock['package']=[p for p in new_lock['package'] if p['name'] not in CRATES]
    assert new_lock==old_lock,'unrelated Cargo.lock changes'
    old_manifest=tomllib.loads(subprocess.check_output(['git','show','HEAD:Cargo.toml'],cwd=ROOT).decode())
    new_manifest=tomllib.loads((ROOT/'Cargo.toml').read_text())
    new_manifest['workspace']['members']=[p for p in new_manifest['workspace']['members'] if p not in CRATES]
    assert new_manifest==old_manifest,'unrelated workspace changes'
    checker=(ROOT/'sunlight-sunfs-check/src/lib.rs').read_text()
    assert 'use sunlight_sunfs::codec::*;' in checker and 'Bootstrap::' not in checker and 'Geometry::calculate' not in checker
    markers={}
    for line in test_logs['release'].splitlines():
        if line.startswith('SFS1_'):markers[line.split()[0]]=line
    corpora={profile:[json.loads(line) for line in (RAW/profile/'fuzz-corpus.jsonl').read_text().splitlines()] for profile in ['dev','release']}
    for rows in corpora.values():assert len(rows)==4096 and all(not row['panic'] for row in rows)
    assert corpora['dev']==corpora['release'],'profile corpus classifications differ'
    geometry=[row for row in performance if row['kind'] in ('geometry','minimum') and row['profile']=='release']
    save('geometry-results.json',{'status':'PASS','rows':geometry,'property_tests':3,'grid_inputs':1500,'boundary_and_cap_tests':'tests/codecs.rs','minimum_explanation':'minimum derived from segment area containing bootstrap closure plus one segment victim + three admitted metadata closures + three publication writes','reserve_qualification':'SFS-1 admission policy only; arbitrary mutation and cleaner progress are SFS-2/SFS-4','record_bytes':{'64':72,'256':96,'512':128},'maximum_segments':{'64':4510,'256':3362,'512':2542}})
    save('codec-validation.json',{'status':'PASS','rust_tests':8,'golden_pages':4,'golden_generator':'tools/sunfs_golden.py','endianness':'explicit little-endian','crc':'CRC-64/ECMA-182 poly 0x42f0e1eba9ea3693 nonreflected init0 xorout0','coverage':'entire 4096-byte metadata page, bytes64..71 zero','structures':['Superblock','copy identity','Checkpoint','generation','NodeId','BlockRef','MapEntry','Inode','DiskTime','DirEntry','Extent','Segment','SummaryEntry and summary page','Orphan','Features','table root/page/descriptor'],'malformed_inputs':4096,'logs':['raw/tests-dev-final.log','raw/tests-release-final.log']})
    save('block-device-contract.json',{'status':'PASS','interface':'sunlight-sunfs/src/block.rs','completion':['Completed (not durable)','Durable','known partial with completed prefix','known failure','uncertain with optional count','UnsupportedDurability'],'capabilities':['logical/physical sector','capacity','alignment','identity','incarnation','max transfer','read_only','flush','FUA'],'aggregation':'Sector512Adapter tested eight-sector writes and no failed-read exposure','flush_contract':'all earlier accepted bytes durable; ordered per byte, independent writes may reorder; no 4KiB atomicity','native_driver_qualification':'NOT_RUN','reset':'synchronous simulator fences all pending work; no real DMA qualification'})
    save('formatter-results.json',{'status':'PASS','empty_geometries':[64,256,512],'initial_checkpoints':[1,2],'ordering':['SB and immutable closure','D0 successful flush','CP1 and CP2','P0 successful flush'],'safety':'create_new, pinned per-component O_NOFOLLOW parent walk, no overwrite, no physical devices','host_adapter_limit_bytes':128*1024*1024,'cli':cli,'commit':False,'push':False})
    save('checker-results.json',{'status':'PASS','independent_semantic_traversal':True,'source':'sunlight-sunfs-check/src/lib.rs','shared':'low-level codec definitions only','cases':['empty 64/256/512 geometries','nonempty data, binding, orphan fixture','7 resealed semantic corruptions','9 nonempty semantic/data corruptions','16 classification/selection cases','read failure','read-only image hash checks'],'exit_codes':{'CLEAN':0,'DEGRADED_RECOVERABLE':1,'CORRUPT':2,'UNSUPPORTED':3,'INDETERMINATE':4},'native_writable_admission':'UNQUALIFIED','page_read_budget_per_candidate':65536,'directory_binding_budget':'maximum_nodes','readonly_cli_hash_unchanged':True})
    save('persistence-tests.json',{'status':'PASS','cases':['acknowledged no-flush lost','successful flush survives','failed flush persists none/some/all without durability success','uncertain write none/all durable','six independent write permutations','same-block order','read failure','reset/incarnation fencing','unsupported flush/FUA','dishonest advertised flush demonstrated separately'],'exhaustive_reorder_bound':'three independent single-sector writes, all 6 permutations','dishonest_model_excluded_from_correctness_verdict':True,'publication_scope':'bootstrap only; D/P/R/R0 mutation protocol deferred SFS-2'})
    save('crash-matrix.json',{'status':'PASS','markers':markers,'boundary_cases_per_profile':112,'fault_cases_per_profile':480,'deterministic_boundary_replays_per_profile':112,'seeds':[0,1,2,0x534653],'tear_offsets':[0,1,511,512,1024,1536,2048,2560,3072,3584,4095,4096],'trace_directories':['raw/dev/crash-traces','raw/release/crash-traces'],'oracle':'independent full closure checker; formatter success requires CLEAN after crash','scope':'finite formatter schedules and three-write reorderings; not exhaustive filesystem mutation safety','initial_attempt':'raw/lab-tests-initial.log: fixture popcount invalid, 11 PASS / 1 FAIL; corrected fixture preserves popcount before semantic check'})
    save('fuzz-results.json',{'status':'PASS','seeds':[0,1,2,0x534653],'per_profile':{'total_inputs':4096,'checker_images':2048,'arbitrary_pages':2048,'typed_payload_decodes':16384},'panics':0,'classification_counts':dict(collections.Counter(row['classification'] for row in corpora['release'])),'corpus':['raw/dev/fuzz-corpus.jsonl','raw/release/fuzz-corpus.jsonl'],'reproduce':'python3 tools/sunfs_reproduce.py --seed N --index N --kind image-mutation --output /tmp/repro.img','unexpected_failing_images':[],'limitation':'bounded malformed-input campaign; no absence-of-bugs proof'})
    save('performance-baseline.json',{'status':'PASS','measurements':performance,'cli_measurement':cli_timing,'host':platform.platform(),'timing_contract':'diagnostic single-host wall-time; codec10000 iterations, simulator format median5, checker mean20; no scores/optimization claims','simulator_memory':'reported buffer capacities only: durable+visible+pending bytes+per-byte persistence masks; trace and allocator overhead excluded','full_table_rewrite_estimate':'three global roots plus node-map/orphan/segment pages; excludes namespace/data/summary changes unless explicitly listed','reevaluate_thresholds':['full global table rewrite >1MiB per commit','metadata closure >10% of usable capacity','measured sync p95 >50ms on intended hardware; NOT_RUN here','more than 82 pages or 6724 nodes needs new format/ADR']})
    assert source_hashes()==sources,'compiled source changed during validation'
    save('commands.json',{'status':'PASS','compiled_source_sha256':sources,'commands':commands,'test_counts':counts,'regression_counts':regression_counts,'categories':{'codec':8,'geometry':3,'laboratory':13,'total':24},'host_profiles':['dev (workspace opt-level=1)','release (opt-level=3 LTO)']})
    summary={'milestone':'SFS-1','overall':'SFS-1 COMPLETE','gates':{f'G{i}':{'status':'PASS','evidence':name} for i,name in enumerate(['source-baseline.json','architecture-implementation-map.json','block-device-contract.json','codec-validation.json','geometry-results.json','formatter-results.json','checker-results.json','crash-matrix.json','commands.json','source-integrity.json'],1)},'tests_per_profile':counts,'regression_tests':sum(regression_counts),'execution_scope':'hosted laboratory and no_std compilation only','native_guest':'NOT_RUN','physical_durability':'UNQUALIFIED','filesystem_mutation_crash_safety':'NOT_RUN','production_mount':False,'boot_root_changes':False,'commit':False,'push':False}
    save('validation-summary.json',summary)
    integrity()
    print('SFS-1 validation complete; report must describe the bounded evidence.',flush=True)
if __name__=='__main__':
    try:main()
    except Exception:
        # Never leave a stale COMPLETE verdict after a later failed campaign.
        save('validation-summary.json',{'milestone':'SFS-1','overall':'SFS-1 INCOMPLETE','status':'FAIL','reason':'validation runner failed; inspect preserved command logs','commit':False,'push':False})
        raise
